def find_hole(I):
    cntI = Counter(x for r in I for x in r)
    return max(cntI, key=lambda v: cntI[v])

def minimal_tile(I, vh=None, hh=None, F=None):
    H, W = len(I), len(I[0])
    T = {}
    for r in range(H):
        for c in range(W):
            if I[r][c] != F:
                key = (r % vh, c % hh) if vh else (r, c)
                if key in T and T[key] != I[r][c]:
                    return None, None
                T[key] = I[r][c]
    return T, True

def solve(I):
    H, W = len(I), len(I[0])
    cnt = Counter(x for r in I for x in r)
    # Hole = color that gets fully overwritten in O -> guess: minority colors?
    # Try candidate set = most common? For demo7 hole=5, count? Let's try all candidates as F and check tile-consistency
    results = []
    for candF in sorted(cnt, key=lambda v: -cnt[v]):
        T, ok = minimal_tile(I, H, W, candF)
        results.append((candF, ok))
    return results

